// Une los fragmentos recuperados del vector store en un solo texto.
// Si la busqueda fallo (error) o no trajo nada, deja un aviso para que el agente no invente.
const base = $('¿Datos completos?').first().json;
const docs = $input.all()
  .map(i => i.json && i.json.document && i.json.document.pageContent)
  .filter(Boolean);
return [{ json: {
  ...base,
  contexto: docs.length ? docs.join('\n---\n') : '(sin información recuperada)',
  contexto_ok: docs.length ? 'si' : 'no'
} }];

parameters.text:
